993	fn tarball_stream_error(
994	    err: streaming::TarballStreamError,
995	    name: &PackageName,
996	    filename: &str,
997	) -> RegistryError {
998	    match err {
999	        streaming::TarballStreamError::Upstream { url, source } => {
1000	            RegistryError::Upstream { url, source }
1001	        }
1002	        streaming::TarballStreamError::Io(err) => RegistryError::Io(err),
1003	        streaming::TarballStreamError::Integrity(err) => {
1004	            tarball_integrity_error(name, filename, format!("integrity verification failed: {err}"))
1005	        }
1006	        streaming::TarballStreamError::TooLarge { limit, received } => tarball_integrity_error(
1007	            name,
1008	            filename,
1009	            format!("tarball body exceeds {limit} byte limit (received {received} bytes)"),
1010	        ),
1011	    }
1012	}
