250	    /// Map the error to the HTTP status the proxy should return to the
251	    /// client. Follows the standard gateway semantics:
252	    ///
253	    /// * `502 Bad Gateway` — upstream returned something we can't make
254	    ///   use of (5xx, malformed JSON, generic transport failure).
255	    /// * `503 Service Unavailable` — couldn't reach upstream at all
256	    ///   (DNS, connection refused, network unreachable). Distinct from
257	    ///   502 so pnpm clients see "service down" rather than "upstream
258	    ///   misbehaved" — both trigger the client's retry loop, but the
259	    ///   distinction matters for monitoring and for any future circuit
260	    ///   breaker.
261	    /// * `504 Gateway Timeout` — upstream took too long to respond.
262	    /// * `400 Bad Request` — client-supplied package or tarball name
263	    ///   wasn't usable. Not retryable.
264	    #[must_use]
265	    pub fn status_code(&self) -> StatusCode {
266	        match self {
267	            RegistryError::Upstream { source, .. } => {
268	                if source.is_timeout() {
269	                    StatusCode::GATEWAY_TIMEOUT
270	                } else if source.is_connect() {
271	                    StatusCode::SERVICE_UNAVAILABLE
272	                } else {
273	                    StatusCode::BAD_GATEWAY
274	                }
275	            }
276	            RegistryError::UpstreamStatus { .. } | RegistryError::TarballIntegrity { .. } => {
277	                StatusCode::BAD_GATEWAY
278	            }
279	            RegistryError::UpstreamUnavailable { .. } => StatusCode::SERVICE_UNAVAILABLE,
280	            RegistryError::InvalidPackageName { .. }
281	            | RegistryError::InvalidTarballName { .. }
282	            | RegistryError::InvalidPolicyPattern { .. }
283	            | RegistryError::InvalidConfig { .. }
284	            | RegistryError::InvalidAttachment { .. }
285	            | RegistryError::BadRequest { .. } => StatusCode::BAD_REQUEST,
286	            RegistryError::Unauthenticated { .. } => StatusCode::UNAUTHORIZED,
287	            RegistryError::Forbidden { .. } => StatusCode::FORBIDDEN,
288	            RegistryError::OsvVulnerability { .. } => StatusCode::FORBIDDEN,
289	            RegistryError::RegistrationDisabled | RegistryError::TooManyUsers { .. } => {
290	                StatusCode::FORBIDDEN
291	            }
292	            RegistryError::Internal { .. }
293	            | RegistryError::InvalidHtpasswdFile { .. }
294	            | RegistryError::Bcrypt(_)
295	            | RegistryError::Sqlite(_)
296	            | RegistryError::JoinError(_) => StatusCode::INTERNAL_SERVER_ERROR,
297	            #[cfg(feature = "backend-libsql")]
298	            RegistryError::Libsql(_) => StatusCode::INTERNAL_SERVER_ERROR,
299	            #[cfg(any(feature = "backend-postgres", feature = "backend-mysql"))]
300	            RegistryError::Sqlx(_) => StatusCode::INTERNAL_SERVER_ERROR,
301	            #[cfg(any(feature = "backend-postgres", feature = "backend-mysql"))]
302	            RegistryError::AuthDatabaseTimeout => StatusCode::GATEWAY_TIMEOUT,
303	            RegistryError::Io(_) | RegistryError::ObjectStore(_) | RegistryError::Json(_) => {
304	                StatusCode::BAD_GATEWAY
305	            }
306	        }
307	    }
