310	fn redact_url_credentials(message: &str) -> String {
311	    let mut redacted = String::with_capacity(message.len());
312	    let mut cursor = 0;
313	    while let Some(relative_scheme_end) = message[cursor..].find("://") {
314	        let scheme_end = cursor + relative_scheme_end;
315	        let scheme_start = find_scheme_start(message, scheme_end);
316	        if scheme_start == scheme_end || !is_valid_scheme(&message[scheme_start..scheme_end]) {
317	            redacted.push_str(&message[cursor..scheme_end + 3]);
318	            cursor = scheme_end + 3;
319	            continue;
320	        }
321	
322	        let url_end = find_url_end(message, scheme_end + 3);
323	        let (candidate, suffix) = split_trailing_punctuation(&message[scheme_start..url_end]);
324	        let Some(safe_url) = redact_url_candidate(candidate) else {
325	            redacted.push_str(&message[cursor..url_end]);
326	            cursor = url_end;
327	            continue;
328	        };
329	
330	        redacted.push_str(&message[cursor..scheme_start]);
331	        redacted.push_str(&safe_url);
332	        redacted.push_str(suffix);
333	        cursor = url_end;
334	    }
335	    redacted.push_str(&message[cursor..]);
336	    redacted
337	}
