}", "newString": "/// Rewrite every `dist.tarball` in `value` to a URL served by *this*
/// registry instead of whatever URL the source put there. The path is
/// keyed by the package name and the upstream tarball's own basename
/// (see [`rewrite_dist_tarball`]), so an uplink cannot point a manifest
/// at a route outside this package's namespace.
///
/// The version-manifest endpoint calls [`extract_version_manifest`],
/// which rewrites its resolved `versions` map entry the same way.
pub fn rewrite_tarball_urls(value: &mut Value, pkg: &PackageName, public_url: &str) {
    let public_url = public_url.trim_end_matches('/');
    if let Some(versions) = value.get_mut("versions").and_then(Value::as_object_mut) {
        for (version, manifest) in versions {
            rewrite_dist_tarball(manifest, pkg, version, public_url);
        }
    }
}

/// Point a single version manifest's `dist.tarball` at this registry,
/// preserving the upstream tarball's basename so a client's later
/// request routes back to *this* version. A non-string or absent
/// `dist.tarball` is left untouched.
fn rewrite_dist_tarball(value: &mut Value, pkg: &PackageName, version: &str, public_url: &str) {
    if value.get("dist").and_then(|dist| dist.get("tarball")).is_none_or(|t| !t.is_string()) {
        return;
    }
    let filename = published_tarball_basename(value, pkg, version).into_owned();
    if let Some(tarball_value) =
        value.get_mut("dist").and_then(Value::as_object_mut).and_then(|dist| dist.get_mut("tarball"))
    {
        *tarball_value = Value::String(format!("{public_url}/{}/-/{filename}", pkg.as_str()));
    }
}

/// Extract the basename of a tarball URL — its last path segment with
/// any `?query` or `#fragment` stripped. Returns `None` when the URL
/// ends in a trailing slash or otherwise has no usable last segment.
///
/// A plain relative basename (no host or path separators) is returned
/// as-is, so this works on both absolute upstream URLs and bare
/// filenames.
pub fn tarball_basename(url: &str) -> Option<&str> {
    // A fragment terminates the URL, and a query precedes any fragment;
    // strip the fragment first, then the query, leaving just the path.
    let path = url.split('#').next().unwrap_or(url);
    let path = path.split('?').next().unwrap_or(path);
    let segment = path.rsplit('/').next()?;
    (!segment.is_empty()).then_some(segment)
}

/// The tarball basename a version publishes through this registry: the
/// upstream `dist.tarball` basename when it has one, otherwise the
/// conventional `<name>-<version>.tgz`. [`rewrite_dist_tarball`] emits
/// this basename and [`resolve_tarball_version`] routes by it, so both
/// must derive it identically.
fn published_tarball_basename<'a>(
    manifest: &'a Value,
    pkg: &PackageName,
    version: &str,
) -> Cow<'a, str> {
    manifest
        .get("dist")
        .and_then(|dist| dist.get("tarball"))
        .and_then(Value::as_str)
        .and_then(tarball_basename)
        .map_or_else(|| Cow::Owned(pkg.tarball_name_for_version(version)), Cow::Borrowed)
}

/// Which packument version a client-facing tarball request maps to,
/// keyed by the published basename (see [`resolve_tarball_version`]).
pub enum TarballVersion<'a> {
    /// Exactly one version publishes this basename.
    Resolved(&'a str),
    /// No version publishes it.
    Unknown,
    /// Two or more versions publish the same basename, so the request
    /// can't be bound to a single version's integrity.
    Conflict,
}

/// Find which version in `packument` publishes the tarball whose public
/// basename is `filename`, mirroring what [`rewrite_tarball_urls`]
/// emitted. Two versions sharing a basename yield
/// [`TarballVersion::Conflict`] — the request is ambiguous and must not
/// be served against either version's integrity.
pub fn resolve_tarball_version<'a>(
    packument: &'a Value,
    pkg: &PackageName,
    filename: &str,
) -> TarballVersion<'a> {
    let Some(versions) = packument.get("versions").and_then(Value::as_object) else {
        return TarballVersion::Unknown;
    };
    let mut resolved = None;
    for (version, manifest) in versions {
        if published_tarball_basename(manifest, pkg, version) == filename {
            if resolved.is_some() {
                return TarballVersion::Conflict;
            }
            resolved = Some(version.as_str());
        }
    }
    resolved.map_or(TarballVersion::Unknown, TarballVersion::Resolved)
