394	/// Extract the basename of a tarball URL — its last path segment with
395	/// any `?query` or `#fragment` stripped. Returns `None` when the URL
396	/// ends in a trailing slash or otherwise has no usable last segment.
397	///
398	/// A plain relative basename (no host or path separators) is returned
399	/// as-is, so this works on both absolute upstream URLs and bare
400	/// filenames.
401	pub fn tarball_basename(url: &str) -> Option<&str> {
402	    // A fragment terminates the URL, and a query precedes any fragment;
403	    // strip the fragment first, then the query, leaving just the path.
404	    let path = url.split('#').next().unwrap_or(url);
